package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.*; import org.springframework.data.jpa.repository.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public interface FinancialTransactionRepository extends JpaRepository<FinancialTransaction,Long>{ List<FinancialTransaction> findAllByOrderByOccurredAtDesc(); @Query("select coalesce(sum(case when f.type='INCOME' then f.amount else -f.amount end),0) from FinancialTransaction f") BigDecimal balance(); @Query("select coalesce(sum(case when f.type='INCOME' then f.amount else -f.amount end),0) from FinancialTransaction f where f.occurredAt>=:from and f.occurredAt<:to") BigDecimal balanceBetween(Instant from,Instant to); }
